let lang="uk";
function setLang(l){
  if(!T[l]) return; lang=l; document.documentElement.lang=l;
  document.querySelectorAll("[data-i18n]").forEach(el=>{const v=T[l][el.dataset.i18n]; if(v!=null) el.textContent=v;});
  document.querySelectorAll("[data-i18n-html]").forEach(el=>{const v=T[l][el.dataset.i18nHtml]; if(v!=null) el.innerHTML=v;});
  document.querySelectorAll(".langs button").forEach(b=>b.setAttribute("aria-pressed",b.dataset.lang===l?"true":"false"));
  try{localStorage.setItem("lili-lang",l)}catch(e){}
}
document.querySelectorAll(".langs button").forEach(b=>b.addEventListener("click",()=>setLang(b.dataset.lang)));
(function(){
  let saved=null; try{saved=localStorage.getItem("lili-lang")}catch(e){}
  const h=(location.hash||"").slice(1);
  const nav=(navigator.language||"").slice(0,2).toLowerCase();
  setLang(T[h]?h:(saved&&T[saved]?saved:(T[nav]?nav:"uk")));
})();
