/* credo: wavy rings slowly widening from the centre */
(function(){
  const g=document.getElementById("credoG"); if(!g) return;
  const paths=[...g.querySelectorAll(".wv")], still=matchMedia("(prefers-reduced-motion: reduce)").matches;
  const P=18000; /* one ring's journey, ms */
  function ring(t,k){
    const ph=((t/P)+k/3)%1, R=6+40*ph, op=Math.sin(Math.PI*ph);
    let d="";
    for(let i=0;i<=96;i++){const a=i/96*Math.PI*2;
      const w=1.6*Math.sin(3*a+t*.00035+k*2)+1.1*Math.sin(5*a-t*.00025+k)+0.9*Math.exp(-Math.pow(((a-(t*.0002+k*2.1))%(Math.PI*2)+Math.PI*2)%(Math.PI*2)-Math.PI,2)*3)*Math.sin(9*a+t*.001);
      const r=R+w*(0.4+ph); d+=(i?"L":"M")+(r*Math.cos(a)).toFixed(2)+" "+(r*Math.sin(a)).toFixed(2);}
    paths[k].setAttribute("d",d+"Z"); paths[k].style.opacity=(op*.9).toFixed(2);
  }
  function frame(t){const r=g.getBoundingClientRect(); if(r.bottom>0&&r.top<innerHeight) paths.forEach((_,k)=>ring(t,k)); if(!still) requestAnimationFrame(frame)}
  still?paths.forEach((_,k)=>ring(4000+k*6000,k)):requestAnimationFrame(frame);
})();

/* observer effect: waves calm into lines where attention falls */
(function(){
  const sec=document.querySelector(".obs"), cv=document.getElementById("obsCv"); if(!sec||!cv) return;
  const ctx=cv.getContext("2d"), still=matchMedia("(prefers-reduced-motion: reduce)").matches;
  let W=0,H=0,dpr=1,px=-1,py=-1,last=-1e9,cx=0,cy=0;
  function size(){const r=cv.getBoundingClientRect();dpr=Math.min(2,devicePixelRatio||1);W=r.width;H=r.height;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
  function mv(e){const r=cv.getBoundingClientRect();px=e.clientX-r.left;py=e.clientY-r.top;last=performance.now()}
  sec.addEventListener("pointermove",mv);sec.addEventListener("pointerdown",mv);
  addEventListener("resize",size);size();
  const N=24;
  function draw(t){
    const r=sec.getBoundingClientRect();
    const p=sec.classList.contains("still")?.6:Math.min(1,Math.max(0,(innerHeight-r.top)/(innerHeight+r.height)*1.3));
    const auto=t-last>2500;
    const tx=auto?W*(.68+.18*Math.sin(t*.00023)):px, ty=auto?H*(.5+.3*Math.sin(t*.00031+1)):py;
    cx+=(tx-cx)*.06; cy+=(ty-cy)*.06;
    const R=Math.min(W,H)*(.16+.3*p);
    ctx.clearRect(0,0,W,H);
    for(let i=0;i<N;i++){
      const y0=H*(.12+.76*i/(N-1)), ph=i*.7;
      ctx.beginPath();
      for(let x=0;x<=W;x+=6){
        const dx=x-cx,dy=y0-cy,d=Math.sqrt(dx*dx+dy*dy),a=Math.max(0,Math.min(1,(R-d)/(R*.45)));
        const amp=14*(1-a*a*(3-2*a));
        const y=y0+amp*.5*(Math.sin(x*.018+t*.0011+ph)+Math.sin(x*.011-t*.0007+ph*1.3));
        x?ctx.lineTo(x,y):ctx.moveTo(x,y);
      }
      ctx.strokeStyle="rgba(29,27,24,.32)";ctx.lineWidth=1;ctx.stroke();
      for(let x=24;x<W;x+=48){const dx=x-cx,dy=y0-cy,d=Math.sqrt(dx*dx+dy*dy),a=Math.max(0,Math.min(1,(R-d)/(R*.45)));
        if(a>.05){ctx.globalAlpha=a;ctx.fillStyle="#ec6a2c";ctx.beginPath();ctx.arc(x,y0,2.2,0,6.283);ctx.fill();ctx.globalAlpha=1}}
    }
  }
  if(still){sec.classList.add("still");cx=W*.68;cy=H*.5;draw(0);return}
  cx=W*.68;cy=H*.5;
  (function loop(t){const r=sec.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight)draw(t);requestAnimationFrame(loop)})(0);
})();

/* ouroboros: a snake of beads slowly turning, five stops of the work */
(function(){
  const svg=document.getElementById("ouroSvg"), box=document.getElementById("ouroBtns"), card=document.getElementById("ouroCard"); if(!svg) return;
  const R=92, NS="http://www.w3.org/2000/svg", still=matchMedia("(prefers-reduced-motion: reduce)").matches;
  const g=document.createElementNS(NS,"g"); g.setAttribute("class","snake"); svg.appendChild(g);
  const head=-90, span=338, n=70;
  for(let k=0;k<n;k++){ /* body from just behind the head around to the tail at the mouth */
    const f=k/(n-1), a=(head+12+f*span)*Math.PI/180, r=7.2-5.6*f;
    const c=document.createElementNS(NS,"circle"); c.setAttribute("cx",(R*Math.cos(a)).toFixed(1)); c.setAttribute("cy",(R*Math.sin(a)).toFixed(1)); c.setAttribute("r",r.toFixed(2));
    c.setAttribute("class",k%6===0?"sc o":"sc"); g.appendChild(c);
  }
  const ha=head*Math.PI/180, hx=R*Math.cos(ha), hy=R*Math.sin(ha);
  g.insertAdjacentHTML("beforeend",'<ellipse class="hd" cx="'+(hx+3)+'" cy="'+hy+'" rx="13" ry="9"/><circle class="eye" cx="'+(hx+7)+'" cy="'+(hy-3)+'" r="1.8"/><path class="jaw" d="M'+(hx-9)+' '+(hy-4)+' L'+(hx-15)+' '+(hy-1)+' L'+(hx-9)+' '+(hy+3)+'"/>');
  let rot=0, cur=0, auto=true, last=0;
  const pos=i=>{const a=(-90+i*72)*Math.PI/180;return [122*Math.cos(a),122*Math.sin(a)]};
  for(let i=0;i<5;i++){const b=document.createElement("button");b.type="button";b.textContent="0"+(i+1);const [x,y]=pos(i);
    b.style.left=(50+x/280*100)+"%";b.style.top=(50+y/280*100)+"%";b.addEventListener("click",()=>{auto=false;show(i)});box.appendChild(b)}
  function show(i){cur=i;[...box.children].forEach((b,k)=>b.setAttribute("aria-pressed",k===i));render()}
  function render(){const d=(OURO[lang]||OURO.uk)[cur];card.innerHTML='<p class="mono">0'+(cur+1)+' · '+d[0]+'</p><p class="oq">'+d[1]+'</p>'}
  document.querySelectorAll(".langs button").forEach(b=>b.addEventListener("click",render));
  show(0);
  function frame(t){
    const r=svg.getBoundingClientRect();
    if(r.bottom>0&&r.top<innerHeight){rot=(t/1000*6)%360;g.setAttribute("transform","rotate("+rot.toFixed(2)+")");
      if(auto&&t-last>6500){last=t;show((cur+1)%5)}}
    requestAnimationFrame(frame);
  }
  if(!still) requestAnimationFrame(frame);
})();

/* ouroboros v3: numbers stay, the snake turns clockwise; when its head passes a number, that stage lights up */
(function(){
  const rot=document.getElementById("ouroRot"), list=document.getElementById("ouroList"); if(!rot) return;
  const dia=rot.parentElement, marks=[...dia.querySelectorAll(".om")], items=[...list.querySelectorAll("li")];
  const still=matchMedia("(prefers-reduced-motion: reduce)").matches;
  const HEAD0=-76, SPEED=6; /* head angle in the image (deg), deg per second */
  marks.forEach((m,i)=>{const a=(-90+i*72)*Math.PI/180;m.style.left=(50+50*Math.cos(a))+"%";m.style.top=(50+50*Math.sin(a))+"%"});
  let ang=0,t0=performance.now(),cur=-1,hold=0;
  function set(i){if(i===cur)return;cur=i;items.forEach((li,k)=>li.classList.toggle("on",k===i));marks.forEach((m,k)=>m.classList.toggle("on",k===i))}
  function place(){
    rot.style.transform="rotate("+ang+"deg)";
    const head=((HEAD0+ang)%360+360)%360;
    let best=0,bd=1e9;for(let i=0;i<5;i++){const m=((-90+i*72)%360+360)%360;let d=Math.abs(head-m);d=Math.min(d,360-d);if(d<bd){bd=d;best=i}}
    set(best);
  }
  items.forEach((li,i)=>li.addEventListener("click",()=>{ang=(-90+i*72)-HEAD0;hold=performance.now()+6000;place()}));
  function frame(t){const r=rot.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight&&t>hold)ang+=SPEED*Math.min(.05,(t-t0)/1000);t0=t;place();requestAnimationFrame(frame)}
  place(); if(!still) requestAnimationFrame(frame);
})();

/* water: a still lake that ripples when you move, and clears when you stop */
(function(){
  const cv=document.getElementById("waterCv"); if(!cv) return;
  const ctx=cv.getContext("2d"), img=new Image(), sec=cv.closest("section");
  const still=matchMedia("(prefers-reduced-motion: reduce)").matches;
  img.src="assets/f-kayak.webp";
  let W=0,H=0,dpr=1,E=6,lx=null,ly=null,px=.5,py=.5,last=performance.now();
  function size(){const r=cv.getBoundingClientRect();dpr=Math.min(2,devicePixelRatio||1);W=r.width;H=r.height;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
  function bump(x,y){if(lx!==null){E=Math.min(28,E+Math.hypot(x-lx,y-ly)*.12)}lx=x;ly=y;const r=cv.getBoundingClientRect();px=(x-r.left)/r.width;py=(y-r.top)/r.height}
  sec.addEventListener("pointermove",e=>bump(e.clientX,e.clientY));
  sec.addEventListener("touchmove",e=>{const t=e.touches[0];bump(t.clientX,t.clientY)},{passive:true});
  let sy=scrollY;addEventListener("scroll",()=>{E=Math.min(28,E+Math.abs(scrollY-sy)*.04);sy=scrollY},{passive:true});
  addEventListener("resize",size);
  function draw(t){
    if(!img.complete||!W) return;
    const s=Math.max(W/img.width,H/img.height),iw=img.width*s,ih=img.height*s,ox=(W-iw)/2,oy=(H-ih)/2;
    const amp=E;
    if(amp<.4){ctx.drawImage(img,ox,oy,iw,ih);return}
    const step=3;
    for(let y=0;y<H;y+=step){
      const fy=y/H, near=Math.exp(-Math.pow((fy-py)*3,2));
      const dx=amp*(.35+.65*near)*Math.sin(y*.045+t*.004)+amp*.4*Math.sin(y*.11-t*.006);
      const sy0=(y-oy)/s;
      ctx.drawImage(img,0,sy0,img.width,step/s+1,ox+dx,y,iw,step+1);
    }
  }
  function loop(t){const dt=Math.min(.05,(t-last)/1000);last=t;E*=Math.pow(.25,dt);const r=cv.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight)draw(t);requestAnimationFrame(loop)}
  img.onload=()=>{size();if(still){E=0;draw(0)}else requestAnimationFrame(loop)};
  size();
})();


/* fogged glass: wipe it and the elephant in the room shows; the glass fogs up again */
(function(){
  const cv=document.getElementById("fogCv"); if(!cv) return;
  const ctx=cv.getContext("2d"), fog=document.createElement("canvas"), fx=fog.getContext("2d");
  const img=new Image(); img.src="assets/mammoth.png";
  const still=matchMedia("(prefers-reduced-motion: reduce)").matches;
  let W=0,H=0,dpr=1,lastUser=-1e9,auto=null;
  function size(){const r=cv.getBoundingClientRect();dpr=Math.min(2,devicePixelRatio||1);W=r.width;H=r.height;
    for(const c of [cv,fog]){c.width=W*dpr;c.height=H*dpr}ctx.setTransform(dpr,0,0,dpr,0,0);fx.setTransform(dpr,0,0,dpr,0,0);fillFog(1)}
  function fillFog(a){fx.globalCompositeOperation="source-over";fx.globalAlpha=a;fx.fillStyle="rgb(238,231,221)";fx.fillRect(0,0,W,H);fx.globalAlpha=1}
  function wipe(x,y,r){fx.globalCompositeOperation="destination-out";const g=fx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,"rgba(0,0,0,.9)");g.addColorStop(1,"rgba(0,0,0,0)");fx.fillStyle=g;fx.beginPath();fx.arc(x,y,r,0,6.283);fx.fill()}
  let prev=null;
  function user(e){const r=cv.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(x<0||y<0||x>W||y>H){prev=null;return}
    lastUser=performance.now();const R=Math.max(34,W*.1);
    if(prev){const d=Math.hypot(x-prev[0],y-prev[1]),n=Math.ceil(d/8);for(let i=1;i<=n;i++)wipe(prev[0]+(x-prev[0])*i/n,prev[1]+(y-prev[1])*i/n,R)}else wipe(x,y,R);prev=[x,y]}
  cv.addEventListener("pointermove",user);cv.addEventListener("pointerdown",user);cv.addEventListener("pointerleave",()=>prev=null);
  cv.addEventListener("touchmove",e=>{user(e.touches[0])},{passive:true});
  addEventListener("resize",size);
  function draw(t){
    ctx.clearRect(0,0,W,H);
    if(img.complete&&img.width){const s=Math.min(W*.86/img.width,H*.8/img.height),iw=img.width*s,ih=img.height*s;
      ctx.globalAlpha=.95;ctx.drawImage(img,(W-iw)/2,(H-ih)/2+H*.04,iw,ih);ctx.globalAlpha=1}
    /* idle: an invisible finger wipes a slow stroke now and then */
    if(t-lastUser>3500){if(!auto||auto.p>1)auto={p:0,y:H*(.35+.3*Math.random()),dir:Math.random()<.5?1:-1};
      auto.p+=.006;const x=auto.dir>0?W*(.1+.8*auto.p):W*(.9-.8*auto.p);if(auto.p<=1)wipe(x,auto.y+Math.sin(auto.p*9)*H*.05,Math.max(30,W*.08))}
    fx.globalCompositeOperation="source-over";fx.globalAlpha=.008;fx.fillStyle="rgb(238,231,221)";fx.fillRect(0,0,W,H);fx.globalAlpha=1;
    ctx.globalAlpha=.9;ctx.drawImage(fog,0,0,W,H);ctx.globalAlpha=1;
  }
  function loop(t){const r=cv.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight)draw(t);requestAnimationFrame(loop)}
  size(); img.onload=()=>{if(still){fillFog(.5);draw(0)}else requestAnimationFrame(loop)};
})();

/* a mammoth slowly walks across the About section, right to left */
(function(){
  const w=document.getElementById("walker"), sec=document.getElementById("about"); if(!w) return;
  const anchor=sec.querySelector(".ab-me");
  function placeY(){if(anchor){w.style.top=(anchor.offsetTop+anchor.offsetHeight*.55)+"px"}}
  addEventListener("resize",placeY);addEventListener("load",placeY);placeY();
  if(matchMedia("(prefers-reduced-motion: reduce)").matches){w.style.right="4%";return}
  const DUR=70000;let start=performance.now();
  function f(t){const W=sec.clientWidth,ww=w.offsetWidth,p=((t-start)%DUR)/DUR;const x=W+ww-(W+2*ww)*p;
    const step=Math.sin(p*DUR/420);w.style.transform="translate("+x.toFixed(1)+"px,"+(Math.abs(step)*-3).toFixed(1)+"px) rotate("+(step*.8).toFixed(2)+"deg)";requestAnimationFrame(f)}
  requestAnimationFrame(f);
})();

