/* Beisser bridge: a knot. Pull and it tightens; let go and it loosens, then unravels into a calm line */
(function(){
  const cv=document.getElementById("knotCv"); if(!cv) return;
  const ctx=cv.getContext("2d"), still=matchMedia("(prefers-reduced-motion: reduce)").matches;
  const BG="#efe8de", N=1100;
  let W=0,H=0,dpr=1, t=0,tT=0, u=0,uT=0, drag=null, lastUser=-1e9, freeAt=0, pulled=false, demo0=0;
  function size(){const r=cv.getBoundingClientRect();dpr=Math.min(2,devicePixelRatio||1);W=r.width;H=r.height;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener("resize",size);
  const sm=x=>x<=0?0:x>=1?1:x*x*(3-2*x), mix=(a,b,k)=>a+(b-a)*k;
  // an organic scribble: sums of sines with uneven frequencies
  function K(w,R,cx,cy,jit){
    const ccx=0.40*Math.cos(0.23*w+0.7)+0.08*Math.cos(0.61*w), ccy=0.34*Math.sin(0.31*w+0.2)+0.06*Math.sin(0.83*w), r=0.46+0.12*Math.sin(0.53*w);
    return [cx+R*(ccx+r*Math.cos(w))+jit, cy+R*0.82*(ccy+r*Math.sin(w))+jit*0.6];
  }
  function knotAt(s,now){
    const cx=W/2, cy=H*0.5, R=Math.min(W*0.2,H*0.36)*(1-0.55*t), jit=t*t*1.6*Math.sin(now*0.06);
    const a=0.15,b=0.85, w0=Math.PI, w1=w0+Math.PI*2*7;
    const breathe=1+0.025*Math.sin(now*0.0012)*(1-t);
    if(s>=a&&s<=b) return K(mix(w0,w1,(s-a)/(b-a)),R*breathe,cx,cy,jit);
    const left=s<a, k=left?s/a:(s-b)/(1-b);
    const P=left?K(w0,R*breathe,cx,cy,jit):K(w1,R*breathe,cx,cy,jit), E=left?[-4,cy+H*0.06]:[W+4,cy-H*0.06];
    const C=[mix(E[0],P[0],0.55),mix(E[1],cy,0.9)+ (left?1:-1)*H*0.08*(1-t)];
    const q=left?k:1-k; // q: 0 at edge, 1 at knot
    const x=(1-q)*(1-q)*E[0]+2*(1-q)*q*C[0]+q*q*P[0], y=(1-q)*(1-q)*E[1]+2*(1-q)*q*C[1]+q*q*P[1];
    return [x,y];
  }
  function waveAt(s,now){
    const m=-4, x=mix(m,W-m,s), env=Math.sin(Math.PI*s);
    return [x,H*0.5+H*0.09*env*Math.sin(Math.PI*2*1.15*s+now*0.0007)];
  }
  function draw(now){
    ctx.fillStyle=BG;ctx.fillRect(0,0,W,H);
    const pts=new Array(N);
    for(let i=0;i<N;i++){
      const s=i/(N-1), d=1-Math.abs(s-0.5)*2, p=sm(u*1.7-d*0.7);
      const A=knotAt(s,now), B=waveAt(s,now);
      pts[i]=[mix(A[0],B[0],p),mix(A[1],B[1],p)];
    }
    const lw=mix(2.1,2.9,t), ink=`rgb(${Math.round(mix(29,196,t*0.8))},${Math.round(mix(27,78,t*0.8))},${Math.round(mix(24,40,t*0.8))})`;
    ctx.lineCap="round";ctx.lineJoin="round";
    const CH=5;
    for(let i=0;i+1<N;i+=CH){ // draw in short runs: each run sits over the earlier ones, so crossings read as over/under
      const j=Math.min(N-1,i+CH), b0=Math.max(0,i-4);
      ctx.beginPath();ctx.moveTo(pts[i][0],pts[i][1]);
      for(let k=i+1;k<=j;k++)ctx.lineTo(pts[k][0],pts[k][1]);
      ctx.strokeStyle=BG;ctx.lineWidth=lw+5;ctx.stroke();
      ctx.beginPath();ctx.moveTo(pts[b0][0],pts[b0][1]);
      for(let k=b0+1;k<=j;k++)ctx.lineTo(pts[k][0],pts[k][1]);
      ctx.strokeStyle=ink;ctx.lineWidth=lw;ctx.stroke();
    }
  }
  function step(now){
    const idle=now-lastUser>5000&&drag===null;
    if(idle&&!still){
      if(!demo0)demo0=now;
      const p=((now-demo0)%13000)/1000;
      if(p<2){tT=0;uT=0}
      else if(p<3.6){tT=1}
      else if(p<4.8){tT=0.95}
      else if(p<5.6){tT=0}
      else if(p<9.5){uT=1}
      else{uT=0}
    }else{
      demo0=0;
      if(drag===null){tT=0; if(pulled&&t<0.15){pulled=false;freeAt=now}
        if(freeAt&&now-freeAt>400)uT=1;
        if(freeAt&&now-freeAt>7000){uT=0;freeAt=0}}
    }
    t=mix(t,tT,drag!==null?0.2:0.06);
    u=mix(u,uT,uT>u?0.018:0.03);
    draw(now);
  }
  function loop(now){const r=cv.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight)step(now);requestAnimationFrame(loop)}
  cv.addEventListener("pointerdown",e=>{drag=[e.clientX,e.clientY];lastUser=performance.now();uT=0;freeAt=0;cv.setPointerCapture&&cv.setPointerCapture(e.pointerId)});
  cv.addEventListener("pointermove",e=>{if(!drag)return;lastUser=performance.now();const d=Math.hypot(e.clientX-drag[0],e.clientY-drag[1]);tT=Math.min(1,d/(W*0.2));if(tT>0.35)pulled=true});
  const up=()=>{if(!drag)return;drag=null;lastUser=performance.now()};
  addEventListener("pointerup",up);addEventListener("pointercancel",up);
  size(); if(still){u=0;t=0;draw(0)} else requestAnimationFrame(loop);
})();

