/* v58: voices list */
(function(){
  const box=document.getElementById("vx"); if(!box) return;
  const items=[...box.querySelectorAll(".vx-i")];
  const wide=matchMedia("(min-width:900px)");
  function fit(){ if(!wide.matches){box.style.minHeight="";return;} let h=0; items.forEach(it=>{h=Math.max(h,it.querySelector(".vx-c").offsetHeight)}); box.style.minHeight=h+"px"; place(); }
  let cur=0;
  function place(){ if(!wide.matches){items.forEach(it=>it.querySelector(".vx-d").style.top="");return;}
    const d=items[cur].querySelector(".vx-d"); const top=Math.max(0,Math.min(items[cur].offsetTop,box.offsetHeight-d.offsetHeight-1));
    items.forEach(it=>it.querySelector(".vx-d").style.top=top+"px"); }
  function show(n,user){
    items.forEach((it,i)=>{const on=i===n; it.classList.toggle("on",on); it.querySelector(".vx-row").setAttribute("aria-expanded",on)});
    cur=n; place();
    if(user&&!wide.matches){const r=items[n].getBoundingClientRect(); if(r.top<70) window.scrollTo({top:scrollY+r.top-80,behavior:"smooth"});}
  }
  items.forEach((it,i)=>{
    const row=it.querySelector(".vx-row");
    row.addEventListener("click",()=>show(i,true));
    row.addEventListener("keydown",e=>{if(e.key==="ArrowDown"||e.key==="ArrowUp"){e.preventDefault();const n=(i+(e.key==="ArrowDown"?1:-1)+items.length)%items.length;show(n,true);items[n].querySelector(".vx-row").focus()}});
    it.querySelector(".vx-write").addEventListener("click",e=>{
      const ta=document.getElementById("askText"); if(!ta) return;
      ta.value=L(e.currentTarget.dataset.k); ta.placeholder="";
      document.getElementById("ask").scrollIntoView({behavior:"smooth",block:"center"});
      setTimeout(()=>{ta.focus({preventScroll:true});ta.setSelectionRange(ta.value.length,ta.value.length)},450);
    });
    it.querySelector("img").addEventListener("load",fit);
  });
  addEventListener("resize",fit); document.querySelectorAll(".langs button").forEach(b=>b.addEventListener("click",()=>setTimeout(fit,30)));
  if(document.fonts&&document.fonts.ready) document.fonts.ready.then(fit); setTimeout(fit,60);
})();

/* v61: tangled lines behind "How I work" straighten as you scroll */
(function(){
  const sec=document.getElementById("how"), cv=document.getElementById("howLines"); if(!sec||!cv) return;
  const still=matchMedia("(prefers-reduced-motion: reduce)").matches;
  const ctx=cv.getContext("2d"); const N=22; let W=0,H=0,dpr=1;
  let seed=11; const rnd=()=>(seed=(seed*16807)%2147483647)/2147483647;
  const th=[...Array(N)].map((_,k)=>({k,pts:[...Array(6)].map(()=>[rnd(),rnd()]),ph:rnd()*6.28,col:k%5===2?"#ec6a2c":"#6d665c"}));
  function size(){const r=cv.getBoundingClientRect();dpr=Math.min(2,devicePixelRatio||1);W=r.width;H=r.height;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
  let p=0,time=0,last=-1;
  function draw(){
    ctx.clearRect(0,0,W,H); const e=p*p*(3-2*p);
    th.forEach(t=>{
      const yLine=H*(.08+.84*t.k/(N-1));
      const P=t.pts.map((pt,j)=>{const x=W*j/5;const wob=Math.sin(time*.0005+t.ph+j)*12*(1-e);return [x*e+W*pt[0]*(1-e), yLine*e+(H*pt[1]+wob)*(1-e)]});
      ctx.beginPath();ctx.moveTo(P[0][0],P[0][1]);
      for(let j=1;j<P.length-1;j++){const xc=(P[j][0]+P[j+1][0])/2,yc=(P[j][1]+P[j+1][1])/2;ctx.quadraticCurveTo(P[j][0],P[j][1],xc,yc)}
      ctx.lineTo(P[5][0],P[5][1]);ctx.strokeStyle=t.col;ctx.globalAlpha=.16+.06*e;ctx.lineWidth=1;ctx.stroke();
    });ctx.globalAlpha=1;
  }
  function upd(){const r=sec.getBoundingClientRect();p=still?1:Math.min(1,Math.max(0,(innerHeight*.85-r.top)/(innerHeight*1.05)))}
  function loop(ts){time=ts;const r=sec.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight){upd();if(!(p>=1&&last>=1))draw();last=p}requestAnimationFrame(loop)}
  addEventListener("resize",()=>{size();last=-1});size();requestAnimationFrame(loop);
})();
